export function BrandIcon({
  slug,
  className,
  mono = false,
}: {
  slug: BrandSlug;
  className?: string;
  mono?: boolean;
}) {
  const b = BRANDS[slug];
  return (
    <svg
      viewBox="0 0 24 24"
      aria-hidden="true"
      className={className}
      fill={mono ? "currentColor" : b.hex}
    >
      <path d={b.path} />
    </svg>
  );
}
